import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState([]);

  return (
    <FeedbackContext.Provider value={{ feedback, setFeedback }}>
      {children}
    </FeedbackContext.Provider>
  );
};
```
**Step 2: Create a Feedback Form**

Create a feedback form component that will use the `FeedbackContext` to submit feedback. This component will have an input field for the student to type their feedback and a submit button:
```js
import { useContext } from 'react';
import { FeedbackContext } from './FeedbackContext';

const FeedbackForm = () => {
  const { feedback, setFeedback } = useContext(FeedbackContext);

  const handleFeedbackSubmit = (event) => {
    event.preventDefault();
    const feedbackText = event.target.feedback.value;
    setFeedback((prevFeedback) => [...prevFeedback, feedbackText]);
    event.target.feedback.value = ''; // Clear the input field
  };

  return (
    <form onSubmit={handleFeedbackSubmit}>
      <input type="text" name="feedback" placeholder="Type your feedback" />
      <button type="submit">Submit</button>
    </form>
  );
};
```
**Step 3: Create a Feedback List Component**

Create a feedback list component that will display the feedback submitted by the student. This component will use the `FeedbackContext` to retrieve the feedback and display it in a list:
```js
import { useContext } from 'react';
import { FeedbackContext } from './FeedbackContext';

const FeedbackList = () => {
  const { feedback } = useContext(FeedbackContext);

  return (
    <ul>
      {feedback.map((feedbackItem, index) => (
        <li key={index}>{feedbackItem}</li>
      ))}
    </ul>
  );
};
```
**Step 4: Use the Context and Components**

Now, use the `FeedbackProvider` to wrap your application and pass the `FeedbackContext` to the `FeedbackForm` and `FeedbackList` components:
```js
import React from 'react';
import ReactDOM from 'react-dom';
import { FeedbackProvider } from './FeedbackContext';
import FeedbackForm from './FeedbackForm';
import FeedbackList from './FeedbackList';

const App = () => {
  return (
    <FeedbackProvider>
      <FeedbackForm />
      <FeedbackList />
    </FeedbackProvider>
  );
};

ReactDOM.render(<App />, document.getElementById('root'));
```
