Here is a basic implementation of a pendulum simulation using JavaScript and HTML5 Canvas. It includes the ability to input the initial angle and release the pendulum.

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulation</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <input id="initial-angle" type="number" value="30">
    <button id="release-button">Release</button>
    <canvas id="pendulum-canvas" width="400" height="400"></canvas>
    <script>
        let canvas = document.getElementById('pendulum-canvas');
        let ctx = canvas.getContext('2d');
        let gravity = 9.8; // m/s^2
        let length = 100;
        let angle = 0;
        let velocity = 0;
        let damping = 0.95;
        letReleased = false;
        let previousAngle;

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(canvas.width / 2, canvas.height / 2);
            ctx.lineTo((canvas.width / 2) + Math.sin(angle) * length, (canvas.height / 2) - Math.cos(angle) * length);
            ctx.stroke();

            previousAngle = angle;
            velocity = velocity * damping - gravity / length * Math.sin(angle);
            angle += velocity;
        }

        function update() {
            if (Released) {
                draw();
                requestAnimationFrame(update);
            }
        }

        function release() {
            Released = true;
        }

        document.getElementById('release-button').addEventListener('click', release);

        function start() {
            previousAngle = angle;
            update();
            setInterval(() => {
                angle = 0;
                velocity = 0;
                Released = false;
            }, 10000);
        }

        start();
        document.getElementById('initial-angle').addEventListener('input', (e) => {
            angle = Math.radians(e.target.value);
            velocity = 0;
            Released = false;
        });
        document.body.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                release();
            }
        });

        function Math.radians(degrees) {
            return degrees * Math.PI / 180;
        }
    </script>
</body>
</html>
```

