    def feedforward(self, inputs):
        output = inputs
        for i in range(len(self.layers) - 1):
            output = sigmoid(np.dot(output, self.weights[i]) + self.biases[i])
        return output

    def backpropagation(self, inputs, targets):
        # Forward pass
        output = self.feedforward(inputs)

        # Calculate error
        error = targets - output

        # Backward pass
        for i in range(len(self.layers) - 1):
            deltas = error * sigmoid_derivative(output)
            output = output * (1 - output)
            self.weights[i] -= np.dot(inputs.T, deltas)
            self.biases[i] -= deltas
            error = np.dot(deltas, self.weights[i].T)

    def train(self, inputs, targets, epochs=1000, learning_rate=0.1):
