```
using System;
using System.Net.Mail;
using System.Net;

class EmailSender
{
    static void Main(string[] args)
    {
        // List of email accounts to use in rotation
        string[] emailAccounts = new string[] { "email1@gmail.com", "email2@yahoo.com", "email3@hotmail.com" };

        // List of subscribers
        string[] subscribers = new string[100];

        // Generate some sample subscriber data
        Random random = new Random();
        for (int i = 0; i < 100; i++)
        {
            subscribers[i] = $"Subscriber {i+1}<sub{random.Next(100)}.com>";
        }

        // Create a SmtpClient instance
        SmtpClient smtpClient = new SmtpClient();

        // Set the rotation index
        int rotationIndex = 0;

        // Send emails to each subscriber
        foreach (string subscriber in subscribers)
        {
            // Send the email using the current email account
            SendEmail(smtpClient, emailAccounts[rotationIndex], subscriber);

            // Rotate to the next email account
            rotationIndex = (rotationIndex + 1) % emailAccounts.Length;
        }
    }

    static void SendEmail(SmtpClient smtpClient, string fromAddress, string toAddress)
    {
        // Create a new MailMessage
        MailMessage message = new MailMessage();

        // Set the from and to addresses
        message.From = new MailAddress(fromAddress);
        message.To.Add(toAddress);

        // Set the subject and body
        message.Subject = "Test email from rotation email sender";
        message.Body = "Hello, this is a test email sent from a rotating email sender";

        // Send the email
        smtpClient.Send(message);
    }
}
```
